INSERT IGNORE INTO rules (`id`,`name`,`payload`) VALUES ('public-engineering','工程与验证约束','{"version":1,"updatedAt":"2026-10-15T00:00:00Z","id":"public-engineering","name":"工程与验证约束","shared":true,"priority":100,"content":"先阅读仓库约束并明确范围；只修改任务所需文件。不得泄露凭据，不得伪造测试或交付证据。使用项目现有构建与测试命令，报告真实结果与限制。发布 PR 前检查 diff；未经任务授权不得合并主分支。"}');
