INSERT IGNORE INTO generic_templates (id,name,payload,updated_at) VALUES ('issue-fix-production','通用缺陷修复 SOP','{"Workflow": {"version": 1, "updatedAt": "2026-10-15T00:00:00Z", "id": "issue-fix-production", "name": "通用缺陷修复 SOP", "revision": 1, "status": "published", "description": "先复现，再修复，独立评审并回归。", "sandboxProfileId": "generic-docker", "generic": true, "owner": "LoopForge", "tags": ["public"], "nodes": [{"id": "clarify", "name": "需求定型", "type": "agent", "agentId": "issue-fix-production-clarify", "maxAttempts": 2, "position": {"x": 100, "y": 150}, "artifactOutputs": [{"name": "clarify", "path": "requirement.md", "mediaType": "text/markdown", "required": true}]}, {"id": "design", "name": "方案设计", "type": "agent", "agentId": "issue-fix-production-design", "maxAttempts": 2, "position": {"x": 345, "y": 150}, "artifactOutputs": [{"name": "design", "path": "design.md", "mediaType": "text/markdown", "required": true}]}, {"id": "implement", "name": "开发实现", "type": "agent", "agentId": "issue-fix-production-implement", "maxAttempts": 2, "position": {"x": 590, "y": 150}, "artifactOutputs": [{"name": "implement", "path": "implementation.md", "mediaType": "text/markdown", "required": true}]}, {"id": "review", "name": "独立评审", "type": "agent", "agentId": "issue-fix-production-review", "maxAttempts": 2, "position": {"x": 835, "y": 150}, "artifactOutputs": [{"name": "review", "path": "review.md", "mediaType": "text/markdown", "required": true}]}, {"id": "test", "name": "测试验证", "type": "agent", "agentId": "issue-fix-production-test", "maxAttempts": 2, "position": {"x": 1080, "y": 150}, "artifactOutputs": [{"name": "test", "path": "test-report.md", "mediaType": "text/markdown", "required": true}]}, {"id": "accept", "name": "人工验收", "type": "approval", "maxAttempts": 1, "rejectTo": "implement", "position": {"x": 1325, "y": 150}}, {"id": "deliver", "name": "交付汇总", "type": "agent", "agentId": "issue-fix-production-deliver", "maxAttempts": 2, "position": {"x": 1570, "y": 150}, "artifactOutputs": [{"name": "deliver", "path": "delivery.md", "mediaType": "text/markdown", "required": true}]}], "edges": [{"id": "e-0", "source": "clarify", "target": "design", "when": "success"}, {"id": "e-1", "source": "design", "target": "implement", "when": "success"}, {"id": "e-2", "source": "implement", "target": "review", "when": "success"}, {"id": "e-3", "source": "review", "target": "test", "when": "success"}, {"id": "e-4", "source": "test", "target": "accept", "when": "success"}, {"id": "e-5", "source": "accept", "target": "deliver", "when": "success"}]}, "Agents": [{"version": 1, "updatedAt": "2026-10-15T00:00:00Z", "id": "issue-fix-production-clarify", "name": "需求定型", "instructions": "工作领域：缺陷根因、复现与回归。确认目标、范围、用户、边界与可测试验收标准，输出 requirement.md。不要开始编码。可以不绑定仓库，但必须先取得用户提供的待修代码和复现材料；缺少时明确列出阻塞项并请求补充，不得编造复现或声称已修复。", "executorId": "codebuddy", "rules": ["public-engineering"], "skills": [], "mcpServers": [], "taskPrompt": {"role": "需求定型", "objective": "完成本节点约定的工作并交付产物。", "inputs": ["任务需求：{{input}}", "仓库上下文：{{repository}}"]}}, {"version": 1, "updatedAt": "2026-10-15T00:00:00Z", "id": "issue-fix-production-design", "name": "方案设计", "instructions": "工作领域：缺陷根因、复现与回归。阅读已确认需求与可用代码，写出最小实现方案、接口影响、风险与验证计划到 design.md。未绑定仓库的新项目可在任务工作区设计和实现；修改已有系统或修复缺陷时必须取得相关源码，缺少时明确阻塞并请求补充。", "executorId": "codebuddy", "rules": ["public-engineering"], "skills": [], "mcpServers": [], "taskPrompt": {"role": "方案设计", "objective": "完成本节点约定的工作并交付产物。", "inputs": ["任务需求：{{input}}", "仓库上下文：{{repository}}"]}}, {"version": 1, "updatedAt": "2026-10-15T00:00:00Z", "id": "issue-fix-production-implement", "name": "开发实现", "instructions": "工作领域：缺陷根因、复现与回归。依据 requirement.md 和 design.md 实现需求，保持范围最小；执行适用验证，记录实现、改动和验证到 implementation.md。", "executorId": "codebuddy", "rules": ["public-engineering"], "skills": [], "mcpServers": [], "taskPrompt": {"role": "开发实现", "objective": "完成本节点约定的工作并交付产物。", "inputs": ["任务需求：{{input}}", "仓库上下文：{{repository}}"]}}, {"version": 1, "updatedAt": "2026-10-15T00:00:00Z", "id": "issue-fix-production-review", "name": "独立评审", "instructions": "工作领域：缺陷根因、复现与回归。独立审查改动及测试证据；按严重程度列出有位置与影响的缺陷及修复建议到 review.md。发现阻断问题必须明确写出 REJECT。不得伪造通过结论。", "executorId": "codebuddy", "rules": ["public-engineering"], "skills": [], "mcpServers": [], "taskPrompt": {"role": "独立评审", "objective": "完成本节点约定的工作并交付产物。", "inputs": ["任务需求：{{input}}", "仓库上下文：{{repository}}"]}}, {"version": 1, "updatedAt": "2026-10-15T00:00:00Z", "id": "issue-fix-production-test", "name": "测试验证", "instructions": "工作领域：缺陷根因、复现与回归。根据验收标准执行项目真实测试、构建及必要端到端场景。必要时修复问题并复测。将命令、退出码、结果、未验证范围写到 test-report.md。", "executorId": "codebuddy", "rules": ["public-engineering"], "skills": [], "mcpServers": [], "taskPrompt": {"role": "测试验证", "objective": "完成本节点约定的工作并交付产物。", "inputs": ["任务需求：{{input}}", "仓库上下文：{{repository}}"]}}, {"version": 1, "updatedAt": "2026-10-15T00:00:00Z", "id": "issue-fix-production-deliver", "name": "交付汇总", "instructions": "工作领域：缺陷根因、复现与回归。核对各阶段实际产物与验证证据，将完成内容、真实测试结果、已知限制及交付物清单写到 delivery.md。未绑定仓库时交付任务工作区中的源码和报告，无需 Git Token；仅在用户明确要求且已配置目标 GitHub 仓库及凭据时创建 PR，不得自行合并。", "executorId": "codebuddy", "rules": ["public-engineering"], "skills": [], "mcpServers": [], "taskPrompt": {"role": "交付汇总", "objective": "完成本节点约定的工作并交付产物。", "inputs": ["任务需求：{{input}}", "仓库上下文：{{repository}}"]}}], "Rules": [{"id": "public-engineering", "name": "工程与验证约束", "shared": true, "priority": 100, "content": "先阅读仓库约束并明确范围；只修改任务所需文件。不得泄露凭据，不得伪造测试或交付证据。使用项目现有构建与测试命令，报告真实结果与限制。发布 PR 前检查 diff；未经任务授权不得合并主分支。仓库绑定是可选的：未绑定时在任务工作区创建新项目并交付源码、报告；已有系统的修改或缺陷修复必须取得相关代码，缺少时明确阻塞并请求补充。没有目标仓库和凭据时不执行推送或创建 PR。"}], "Skills": []}',UTC_TIMESTAMP());
INSERT IGNORE INTO generic_templates (id,name,payload,updated_at) VALUES ('generic-product-delivery','通用产品方案 SOP','{"Workflow": {"version": 1, "updatedAt": "2026-10-15T00:00:00Z", "id": "generic-product-delivery", "name": "通用产品方案 SOP", "revision": 1, "status": "published", "description": "完成需求分析、产品方案文档与独立验收；无需代码仓库或 Git Token。", "sandboxProfileId": "generic-docker", "generic": true, "owner": "LoopForge", "tags": ["public"], "nodes": [{"id": "clarify", "name": "需求定型", "type": "agent", "agentId": "generic-product-delivery-clarify", "maxAttempts": 2, "position": {"x": 100, "y": 150}, "artifactOutputs": [{"name": "clarify", "path": "requirement.md", "mediaType": "text/markdown", "required": true}]}, {"id": "design", "name": "方案设计", "type": "agent", "agentId": "generic-product-delivery-design", "maxAttempts": 2, "position": {"x": 345, "y": 150}, "artifactOutputs": [{"name": "design", "path": "design.md", "mediaType": "text/markdown", "required": true}]}, {"id": "review", "name": "独立评审", "type": "agent", "agentId": "generic-product-delivery-review", "maxAttempts": 2, "position": {"x": 590, "y": 150}, "artifactOutputs": [{"name": "review", "path": "review.md", "mediaType": "text/markdown", "required": true}]}, {"id": "accept", "name": "人工验收", "type": "approval", "maxAttempts": 1, "rejectTo": "design", "position": {"x": 835, "y": 150}}, {"id": "deliver", "name": "交付汇总", "type": "agent", "agentId": "generic-product-delivery-deliver", "maxAttempts": 2, "position": {"x": 1080, "y": 150}, "artifactOutputs": [{"name": "deliver", "path": "delivery.md", "mediaType": "text/markdown", "required": true}]}], "edges": [{"id": "e-0", "source": "clarify", "target": "design", "when": "success"}, {"id": "e-1", "source": "design", "target": "review", "when": "success"}, {"id": "e-2", "source": "review", "target": "accept", "when": "success"}, {"id": "e-3", "source": "accept", "target": "deliver", "when": "success"}]}, "Agents": [{"version": 1, "updatedAt": "2026-10-15T00:00:00Z", "id": "generic-product-delivery-clarify", "name": "需求定型", "instructions": "工作领域：产品方案、用户场景与验收规范。确认目标、范围、用户场景、业务边界与可检查的验收标准，输出 requirement.md。信息不足时明确列出假设和待确认项。", "executorId": "codebuddy", "rules": ["public-product-documents"], "skills": [], "mcpServers": [], "taskPrompt": {"role": "需求定型", "objective": "完成本节点约定的工作并交付产物。", "inputs": ["任务需求：{{input}}", "仓库上下文：{{repository}}"]}}, {"version": 1, "updatedAt": "2026-10-15T00:00:00Z", "id": "generic-product-delivery-design", "name": "方案设计", "instructions": "工作领域：产品方案、用户场景与验收规范。阅读 requirement.md，梳理用户旅程、功能范围、交互流程、业务规则、风险和验收标准，将产品方案写到 design.md。只交付文档，无需代码仓库，不执行编码或 Git 操作。", "executorId": "codebuddy", "rules": ["public-product-documents"], "skills": [], "mcpServers": [], "taskPrompt": {"role": "方案设计", "objective": "完成本节点约定的工作并交付产物。", "inputs": ["任务需求：{{input}}", "仓库上下文：{{repository}}"]}}, {"version": 1, "updatedAt": "2026-10-15T00:00:00Z", "id": "generic-product-delivery-review", "name": "独立评审", "instructions": "工作领域：产品方案、用户场景与验收规范。依据 requirement.md 独立审查 design.md 的完整性、一致性、边界场景与验收标准。将具体问题、文档位置、影响及修改建议写到 review.md。发现阻断问题必须明确写出 REJECT；不得伪造验证结论。", "executorId": "codebuddy", "rules": ["public-product-documents"], "skills": [], "mcpServers": [], "taskPrompt": {"role": "独立评审", "objective": "完成本节点约定的工作并交付产物。", "inputs": ["任务需求：{{input}}", "仓库上下文：{{repository}}"]}}, {"version": 1, "updatedAt": "2026-10-15T00:00:00Z", "id": "generic-product-delivery-deliver", "name": "交付汇总", "instructions": "工作领域：产品方案、用户场景与验收规范。在人工验收后核对 requirement.md、design.md 和 review.md，将实际完成内容、验收结论、待确认问题、已知限制及交付物清单写到 delivery.md。只交付工作区文档，无需 Git Token，不创建代码提交或 PR。", "executorId": "codebuddy", "rules": ["public-product-documents"], "skills": [], "mcpServers": [], "taskPrompt": {"role": "交付汇总", "objective": "完成本节点约定的工作并交付产物。", "inputs": ["任务需求：{{input}}", "仓库上下文：{{repository}}"]}}], "Rules": [{"id": "public-product-documents", "name": "产品文档与验收约束", "shared": true, "priority": 100, "content": "根据用户输入和工作区文档完成产品方案；无需代码仓库、Git Token 或代码构建。明确假设与待确认项，不得伪造事实、验证或验收结果，不得泄露凭据。文档写入任务工作区并按节点约定归档；发现阻断问题明确说明并返工。"}], "Skills": []}',UTC_TIMESTAMP());
INSERT IGNORE INTO workflows (`id`,`name`,`payload`,`version`,`revision`,`status`) VALUES ('welcome-workflow','平台验收 · 脚本与审批','{"version":1,"updatedAt":"2026-10-15T00:00:00Z","id":"welcome-workflow","name":"平台验收 · 脚本与审批","revision":1,"status":"published","projectId":"welcome","description":"无需模型密钥。真实运行脚本、查看产物，在人工审批后继续执行。","sandboxProfileId":"local","nodes":[{"id":"prepare","name":"生成验收报告","type":"script","scriptLanguage":"shell","executionScope":"run","script":"mkdir -p reports\\nprintf ''# LoopForge 本地验收\\\\n\\\\n已验证：真实脚本节点、持久化产物、人工审批与恢复。\\\\n'' > reports/welcome.md","maxAttempts":1,"position":{"x":100,"y":150},"artifactOutputs":[{"name":"welcome","path":"reports/welcome.md","mediaType":"text/markdown","required":true}]},{"id":"approve","name":"请确认验收报告","type":"approval","maxAttempts":1,"rejectTo":"prepare","position":{"x":370,"y":150}},{"id":"finish","name":"完成验收","type":"script","scriptLanguage":"shell","executionScope":"run","script":"printf ''# 验收完成\\\\n\\\\n审批已通过，执行成功恢复。\\\\n'' > completed.md","artifactOutputs":[{"name":"completed","path":"completed.md","mediaType":"text/markdown","required":true}],"maxAttempts":1,"position":{"x":640,"y":150}}],"edges":[{"id":"e-1","source":"prepare","target":"approve","when":"success"},{"id":"e-2","source":"approve","target":"finish","when":"success"}]}',1,1,'published');
INSERT IGNORE INTO agents (id,name,payload,updated_at) VALUES ('baseline-align-resolver','基线对齐执行员','{"id": "baseline-align-resolver", "name": "基线对齐执行员", "version": 1, "shared": true, "executorId": "codebuddy", "instructions": "只做基线对齐：fetch 默认分支并 merge 到当前工作分支；解决冲突时保留双方有效实现，拿不准时记录取舍。创建本地合并提交。不要自行 push 或修改默认分支，不要执行与本次基线对齐无关的测试或编写修复报告。", "rules": ["public-engineering"], "skills": [], "mcpServers": []}',UTC_TIMESTAMP());
